   150→  imports: ImportSpecifier[];  // Named imports
   151→  from: string;                // Module path (relative or absolute)
   152→  isNamespace?: boolean;       // import * as name
   153→  namespace?: string;          // Namespace name if isNamespace
   154→}
   155→
   156→// Export statement
   157→export interface ExportStatement {
   158→  type: 'export';
   159→  declaration: FunctionStatement | VariableDeclaration;  // What to export
   160→}
   161→
   162→// Module (top-level container for a .fl file)
   163→export interface Module {
   164→  path: string;                // File path or module name
   165→  imports: ImportStatement[];  // Import statements at top
   166→  exports: ExportStatement[];  // Export statements
   167→  statements: Statement[];     // Other statements (functions, variables, etc.)
   168→  lintConfig?: LintConfig;     // Native-Linter: @lint(...) 어노테이션
   169→  allowOrigins?: string[];     // Hardware-CORS: @allow_origin("https://...") 도메인 화이트리스트
   170→  cspPolicy?: string;          // Native-CSP-Shield: @csp_policy(...) 직렬화 문자열
   171→  validateSchemas?: Array<{ name: string; schema: string }>;  // Native-Request-Validator: @validate_schema(...)
   172→  localVault?: LocalVaultConfig; // Native-JSON-Vault: @local_vault(path: "...", autosave: true)
   173→}
   174→
   175→/**
   176→ * Native-JSON-Vault: @local_vault(...) 어노테이션 설정
   177→ *
   178→ * 예시:
   179→ *   @local_vault(path: "./data/config.json", autosave: true)
   180→ */
   181→export interface LocalVaultConfig {
   182→  path: string;        // vault 파일 경로
   183→  autosave: boolean;   // 쓰기 즉시 commit 여부
   184→  line: number;
   185→  column: number;
   186→}
   187→
   188→/**
   189→ * Native-Linter: @lint(...) 어노테이션 설정
   190→ *
   191→ * 예시:
   192→ *   @lint(no_unused: error, shadowing_check: warn, strict_pointers: true)
   193→ */
   194→export interface LintConfig {
   195→  no_unused?: 'error' | 'warn' | 'off';      // 미사용 변수 감지
   196→  shadowing_check?: 'error' | 'warn' | 'off'; // 변수 섀도잉 감지
   197→  strict_pointers?: boolean;                  // 포인터 안전성 강제
   198→  line: number;   // 어노테이션 소스 위치
   199→  column: number;
   200→}
   201→
   202→/**
   203→ * Phase 15: Pattern Matching
   204→ * Rust 스타일의 match 표현식 지원
   205→ */
   206→
   207→// Pattern 타입 (5가지 패턴)
   208→export type Pattern =
   209→  | LiteralPattern
   210→  | VariablePattern
   211→  | WildcardPattern
   212→  | StructPattern
   213→  | ArrayPattern;
   214→
   215→export interface LiteralPattern {
   216→  type: 'literal';
   217→  value: string | number | boolean;
   218→}
   219→
   220→export interface VariablePattern {
   221→  type: 'variable';
   222→  name: string;
   223→}
   224→
   225→export interface WildcardPattern {
   226→  type: 'wildcard';
   227→}
   228→
   229→export interface StructPattern {
   230→  type: 'struct';
   231→  fields: Record<string, Pattern>;
   232→}
   233→
   234→export interface ArrayPattern {
   235→  type: 'array';
   236→  elements: Pattern[];
   237→}
   238→
   239→// Match arm (패턴 → 표현식)
   240→export interface MatchArm {
   241→  pattern: Pattern;
   242→  guard?: Expression;  // if 조건 (선택사항)
   243→  body: Expression;
   244→}
   245→
   246→// Match 표현식
   247→export interface MatchExpression {
   248→  type: 'match';
   249→  scrutinee: Expression;  // 매칭할 값
   250→  arms: MatchArm[];
   251→}
   252→
   253→// Reified-Type-System: 제네릭 타입 파라미터
   254→// struct User<T: Printable> → typeParams: [{ name: 'T', constraint: 'Printable' }]
   255→export interface GenericTypeParam {
   256→  name: string;           // 'T', 'U', 'K', 'V' 등
   257→  constraint?: string;    // 'Printable', 'Comparable' 등 (선택)
   258→}
   259→
   260→// Compile-Time-ORM: @db_table / @db_column 어노테이션 타입
   261→export interface ORMAnnotation {
   262→  name: string;                     // 'db_table' | 'db_column' | 'db_id' | 'db_auto_inc'
   263→  args?: Record<string, string>;    // 예: { name: 'wash_logs' } or { type: 'varchar(255)' }
   264→}
   265→
   266→// Compile-Time-Validator: @check(min:N, max:N, pattern:"...") 어노테이션
   267→// @check(min: 3, max: 20)           → 길이/크기 범위 검증
   268→// @check(pattern: "^[a-z]+$")       → 정규표현식 검증 (SIMD 가속)
   269→// @check(min: 0, max: 100, pattern: "^\\d+$") → 복합 검증
   270→export interface CheckConstraint {
   271→  min?: number;      // string: 최소 길이, number: 최솟값
   272→  max?: number;      // string: 최대 길이, number: 최댓값
   273→  pattern?: string;  // 정규표현식 패턴 (SIMD-accelerated matching)
   274→  required?: boolean; // 필수 필드 여부 (기본 true)
   275→}
   276→
   277→// Phase 16: Struct Declaration
   278→// Reified-Type-System: typeParams 추가 → struct User<T> { id: T, name: string }
   279→// Compile-Time-ORM: annotations 추가 → @db_table(name: "wash_logs") struct WashLog { ... }
   280→// Compile-Time-Validator: checkConstraints 추가 → @check(min:3, max:20) username: string
   281→export interface StructDeclaration {
   282→  type: 'struct';
   283→  name: string;
   284→  typeParams?: GenericTypeParam[];   // Reified-Type-System: 제네릭 파라미터
   285→  fields: Array<{
   286→    name: string;
   287→    fieldType?: string;
   288→    annotations?: ORMAnnotation[];       // Compile-Time-ORM: @db_id, @db_column(type: .varchar)
   289→    checkConstraints?: CheckConstraint;  // Compile-Time-Validator: @check(...) 검증 규칙
   290→  }>;
   291→  annotations?: ORMAnnotation[];     // Compile-Time-ORM: @db_table(name: "...") 등
   292→  secureToken?: SecureTokenAnnotation; // Native-Auth-Token: @secure_token(...)
   293→}
   294→
   295→// Reified-Type-System: 타입 별칭 선언
   296→// type UserID = int | string       → alias: 'UserID', definition: 'int | string', isUnion: true
   297→// type Callback = fn(int) -> bool  → alias: 'Callback', definition: 'fn(int)->bool'
   298→export interface TypeAliasDeclaration {
   299→  type: 'typeAlias';
   300→  alias: string;          // 타입 별칭명 (예: 'UserID')
   301→  definition: string;     // 원본 타입 표현 (예: 'int | string')
   302→  isUnion: boolean;       // 유니온 타입 여부
   303→  members?: string[];     // 유니온 멤버들 (isUnion이 true일 때)
   304→  line: number;
   305→  column: number;
   306→}
   307→
   308→// Reified-Type-System: 컴파일 타임 크기 검증
   309→// @static_assert_size<User<int>, 24>  → 런타임 오버헤드 없이 타입 레이아웃 검증
   310→export interface StaticAssertDeclaration {
   311→  type: 'staticAssert';
   312→  targetType: string;     // 검증할 타입 (예: 'User<int>')
   313→  expectedSize: number;   // 기대 바이트 크기 (예: 24)
   314→  line: number;
   315→  column: number;
   316→}
   317→
   318→// Phase 16: Enum Declaration
   319→export interface EnumDeclaration {
   320→  type: 'enum';
   321→  name: string;
   322→  fields: { [key: string]: number };
   323→}
   324→
   325→// Phase 16: Break Statement
   326→export interface BreakStatement {
   327→  type: 'break';
   328→}
   329→
   330→// Phase 16: Continue Statement
   331→export interface ContinueStatement {
   332→  type: 'continue';
   333→}
   334→
   335→// Native-Auth-Token: @secure_token 어노테이션이 붙은 구조체 메타데이터
   336→// @secure_token(algo: .hmac_sha256, expires: 3600)
   337→// struct AuthClaims { user_id: int, role: string }
   338→export interface SecureTokenAnnotation {
   339→  algo: 'hmac_sha256' | 'sha256';  // 서명 알고리즘
   340→  expires: number;                  // 기본 만료 시간 (초)
   341→}
   342→
   343→// Secret-Link: 보안 변수 선언 (빌드 타임 주입 + 암호화 메모리)
   344→export interface SecretDeclaration {
   345→  type: 'secret';
   346→  name: string;                    // 보안 변수명
   347→  source?: 'config' | 'literal';   // 값 출처: .flconf 또는 리터럴
   348→  value?: Expression;              // 리터럴 값 (빌드 타임에 암호화)
   349→  configKey?: string;              // .flconf 키 (Config.load("KEY"))
   350→}
   351→
   352→// MOSS-Style: 제로-런타임 스타일 속성
   353→export interface StyleProperty {
   354→  name: string;           // background, padding, font-size 등
   355→  value: string | number; // #007bff, 10, "bold" 등
   356→  unit?: string;          // px, em, rem, % 등
   357→}
   358→
   359→// MOSS-Style: 제로-런타임 스타일 선언
   360→export interface StyleDeclaration {
   361→  type: 'style';
   362→  name: string;           // 스타일 이름 (primary_button 등)
   363→  properties: StyleProperty[];
   364→  extends?: string;       // 상속할 스타일 이름 (선택)
   365→}
   366→
   367→// Self-Testing Compiler: 내장 테스트 블록
   368→// - test 모드: 함수로 래핑하여 실행
   369→// - 릴리즈 빌드: IR Generator가 완전히 skip (0바이트)
   370→export interface TestBlock {
   371→  type: 'test';
   372→  name: string;        // test "이름"
   373→  body: Statement[];   // 블록 내용
   374→  modifier?: 'skip' | 'only';  // test.skip / test.only
   375→  line: number;        // 소스 위치 (오류 추적용)
   376→  column: number;
   377→}
   378→
   379→// Self-Testing Compiler: expect 어서션
   380→// expect(actual).to.be.equal(expected) → assert_eq(actual, expected, desc) 호출로 컴파일
   381→// - test 블록 내에서 사용 → 릴리즈에서는 test 블록 자체가 0바이트이므로 자동 제거
   382→// - 지원 형식:
   383→//     expect(x).to.be.equal(y)    → kind='equal'   (assert_eq)
   384→//     expect(x).to.be.notEqual(y) → kind='notEqual' (assert_ne)
   385→//     expect(x).to.be.true()      → kind='true'     (assert_true)
   386→//     expect(x).to.be.false()     → kind='false'    (assert_false)
   387→//     expect(x).to.be.exists()    → kind='exists'   (assert)
   388→export interface AssertStatement {
   389→  type: 'assert';
   390→  kind: 'equal' | 'notEqual' | 'true' | 'false' | 'exists';
   391→  actual: Expression;
   392→  expected?: Expression;   // equal / notEqual에서 사용
   393→  sourceDesc: string;      // "[line:col] expect(...).to.be.xxx(...)" - 에러 메시지용
   394→  line: number;
   395→  column: number;
   396→}
   397→
   398→// 문장 (Statement)
   399→export type Statement =
   400→  | ExpressionStatement
   401→  | VariableDeclaration
   402→  | IfStatement
   403→  | ForStatement
   404→  | ForOfStatement  // Phase 2: for...of loop support
   405→  | WhileStatement
   406→  | ReturnStatement
   407→  | BlockStatement
   408→  | ImportStatement  // Phase 4: Module System
   409→  | ExportStatement  // Phase 4: Module System
   410→  | TryStatement    // Phase I: Exception Handling
   411→  | ThrowStatement  // Phase I: Exception Handling
   412→  | StructDeclaration  // Phase 16: Struct support
   413→  | EnumDeclaration    // Phase 16: Enum support
   414→  | BreakStatement     // Phase 16: Break support
   415→  | ContinueStatement  // Phase 16: Continue support
   416→  | SecretDeclaration  // Secret-Link: 보안 변수
   417→  | StyleDeclaration   // MOSS-Style: 스타일 선언
   418→  | TestBlock               // Self-Testing Compiler: 내장 테스트 블록
   419→  | AssertStatement         // Self-Testing Compiler: expect 어서션
   420→  | TypeAliasDeclaration    // Reified-Type-System: type X = A | B
   421→  | StaticAssertDeclaration; // Reified-Type-System: @static_assert_size<T, N>
   422→
   423→export interface ExpressionStatement {
   424→  type: 'expression';
   425→  expression: Expression;
   426→}
   427→
   428→export interface VariableDeclaration {
   429→  type: 'variable';
   430→  name: string;
   431→  varType?: string;
   432→  value?: Expression;
   433→  mutable?: boolean;  // Phase 16: let vs let mut
   434→}
   435→
   436→export interface IfStatement {
   437→  type: 'if';
   438→  condition: Expression;
   439→  consequent: BlockStatement;
   440→  alternate?: BlockStatement;
   441→}
   442→
   443→export interface ForStatement {
   444→  type: 'for';
   445→  variable: string;
   446→  iterable: Expression;
   447→  body: BlockStatement;
   448→}
   449→

